read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();e=html.escape
codes=['M12','M13','M14','M15','S11','S12'];notes={m['code']:m for m in read(O/'design-notes.json')['maps']}
